MagickBooleanType WritePSDImage(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, MagickBooleanType separate, ExceptionInfo *exception) {
    size_t width, height;
    ssize_t y;
    Quantum *pixels;
    MagickBooleanType status;
    CompressionType compression;

    if (image == (Image *) NULL)
        return MagickFalse;

    width = image->columns;
    height = image->rows;

    compression = (CompressionType) psd_info->compression;

    pixels = (Quantum *) AcquireQuantumMemory(width, sizeof(*pixels));
    if (pixels == (Quantum *) NULL)
        return MagickFalse;

    status = MagickTrue;
    for (y = 0; y < (ssize_t) height; y++) {
        if (y == 0)
            if (SetImageProgress(image, WriteImageTag, 0, 1) == MagickFalse)
                break;

        (void) ExportQuantumPixels(image, (CacheView *) NULL, pixels, GrayQuantum, width, exception);

        if (compression == RLECompression)
            PackbitsCompress(pixels, width);

        if (WriteBlob(image->file, width, pixels) != width)
            status = MagickFalse;

        if (SetImageProgress(image, WriteImageTag, (MagickRealType) (y + 1) / height, 1) == MagickFalse)
            break;
    }

    pixels = (Quantum *) RelinquishMagickMemory(pixels);

    if (image->alpha_trait != UndefinedPixelTrait) {
        pixels = (Quantum *) AcquireQuantumMemory(width, sizeof(*pixels));
        if (pixels == (Quantum *) NULL)
            return MagickFalse;

        for (y = 0; y < (ssize_t) height; y++) {
            (void) ExportQuantumPixels(image, (CacheView *) NULL, pixels, AlphaQuantum, width, exception);

            if (compression == RLECompression)
                PackbitsCompress(pixels, width);

            if (WriteBlob(image->file, width, pixels) != width)
                status = MagickFalse;

            if (SetImageProgress(image, WriteImageTag, (MagickRealType) (y + 1) / height, 1) == MagickFalse)
                break;
        }

        pixels = (Quantum *) RelinquishMagickMemory(pixels);
    }

    return status;
}

